}

pub fn run_context_with_cancel_and_hooks(
    cancel: CancellationToken,
    hooks: Vec<Arc<dyn Hook<()>>>,
) -> RunContext<()> {
    let mut registry = HookRegistry::new();
    for h in hooks {
        registry.push(h);
    }
    RunContext::ephemeral(())
        .with_session(Arc::new(NoopSession))
        .with_hooks(registry)
        .with_cancel(cancel)
}

